			cheerleader.offset.y = 2;
			add(cheerleader);
			add(new Girl2(200, 168));
			for (i = 0; i < 24; i++)
			{
				bg = new FlxSprite(0, 10 * i);
				bg.makeGraphic(1920, 10, 4279308561, false);
				bg.alpha = i / 24.0;
				bgObjects.add(bg);
			}

			for (i = 0; i < 31; i++)
			{
				bgObjects.add(new Tel(64 * i - 40, 136, scale));
			}

			fadeToBlack = new FlxSprite(0, 0);
			fadeToBlack.makeGraphic(320, 240, 4294967295, false);
			add(fadeToBlack);
			player.walkingSound = false;
			player.jumpEnable = false;
			player.moveEnable = false;
			player.maxVelocity.x = 40;
			camera = new FlxSprite(-320, -120);
			camera.alpha = 0;
			camera.height = 480;
			camera.width = 160;
			camera.centerOffsets();
			add(camera);
			credits = new FlxGroup();
			addCredits();
			for (i = 0; i < 9; i++)
			{
				bg1 = new FlxSprite(1720 + 20 * i, 0);
				bg1.makeGraphic(20, 240, 4278190080, false);
				bg1.alpha = 0.1 * (i + 1);
				narrators.add(bg1);
			}

			FlxSprite bg2 = new FlxSprite(1900, 0);
			bg2.makeGraphic(2000, 240, 4278190080, false);
			narrators.add(bg2);
			add(credits);
			FlxG.camera.setBounds(0, 0, 3840, 240, true);
			FlxG.camera.follow(camera, FlxCamera.STYLE_LOCKON);
		}

		public override void update()
		{
			base.update();
			FlxG.overlap<FlxSprite, NarratorTouch>(camera, credits, makeCreditVisible);
			FlxG.collide(level, cheerleader);
			++count;
			if (count == 60)
			{
				bgObjects.add(new Cloud(player, true));
				count = 0;
			}

			if (player.x < 4)
			{
				player.x = 4;
			}
			else if (player.x > 164)
			{
				player.x = 164;
			}

			if (!gecis && player.x > 152)
			{
				camera.velocity.x = 30;
				FlxG.play(drama);
				gecis = true;
				new FlxTimer().start(22, 1, playMusic);
			}

			if (fadeToBlack.alpha > 0.9)
			{
				fadeToBlack.alpha -= 0.0005;
			}
			else if (fadeToBlack.alpha > 0)
			{
				fadeToBlack.alpha -= 0.004;
			}
			else if (!player.moveEnable && fadeToBlack.alpha <= 0)
			{
				player.moveEnable = true;
			}

			if (camera.x > 2104)
			{
				nextLevel();
			}

			if (camera.velocity.x > 0)
			{
				if (FlxG.keys.ENTER && camera.velocity.x > 0)
				{
					camera.velocity.x = 100;
				}
				else
				{
					camera.velocity.x = 30;
				}
			}
		}

		private void playMusic(FlxTimer a)
		{
			FlxG.playMusic(music, 1);
		}

		public override void addBgDetail()
		{
			int i = 0;
			int j = 0;
			for (i = 0; i < 30; i++)
